out = []
for (addr, rec, off, calterm, desc, h, field, recv, raddr, rrec, taddr, tval, trec, slot, c848, spn, mv, cmpi, name) in rows:
    a = int(addr, 16)
    eeprom_offset = a - 0x803b0a
    spn_text = f' ({spn})' if spn else ''
    ev = (f"{h[0]} (cm550_FUN_00021ef6 registers it with 0x21272 for {h[1]}) reads this byte with move.b, compares it with can_received_source_address (0x80d9dc) using cmp.b, then compares it with 0xFF using cmpi.b #255. "
          f"When it equals the sender's source address, or is 0xFF (any source), the handler reloads timeout word {taddr} with {tval} (by arithmetic e2m {trec}; see notes) and stores {field} in {recv} ({raddr}, e2m {rrec}). "
          f"Otherwise the handler ignores that signal from that sender. The ROM has no other absolute reference to this byte. "
          f"CM848 twin: j1939_input_source_address_filter_cal[{slot}] (0x3fd81e + {slot}) in {h[2]}, which gates {c848}{spn_text}. "
          f"The slot is the e2m offset - 6 in both firmwares. Dump: 0xFF in RAM and at EEPROM 0x{eeprom_offset:03x} (accept any source). "
          f"The address is in the EEPROM mirror (0x803B0A-0x804155), so the name takes _cal.")
    if rec == 'MXWTPRSA':
        ev += (" The consumer scales the value as a pressure. cm550_FUN_00020fac tests timeout 0x804246 (slot 9) and multiplies the value by 0x2442 / 100 = 92.82. "
               "That is 128 x 0.7252683, the JCWTPRMU psi per bit (5 kPa/bit), which converts it to a 1/128 unit. The pedal inputs use << 4 / 10 (0.4 %/bit) instead. "
               "Contrary label, disclosed: the consumer stores the result in 0x80a760, which the e2m calls 12D3 +0 ADIMTPUR 'INTAKE MANIFOLD TEMPERATURE RAW USER VALUE' (scale 1/128), and the priority it tests is the global named priority_of_client_overriding_raw_intake_manifold_temperature_0_ff. "
               "The label of that destination is unresolved. The name rests on the three wet tank records (MXWTPRSA, the timer MXWTPRTR, the value JCWTPRMU) and the 92.82 pressure scale. "
               "CM848's slot 9 receiver 0x40aaba is named j1939_received_accelerator_pedal_position_2, but its own e2m record is 12F7 +14 J1939_Mux_Wet_Tank_Pressure (JCWTPRMU). The CM848 name is the misnamed one, so it is not reused here.")
    out.append(dict(
        address=addr,
        current_label='DAT_' + addr[2:],
        action='name',
        proposed_name=name,
        proposed_type='byte',
        confidence='high',
        e2m_records=(f"{rec} (Calterm name {calterm}, from the CM848 e2m, which has the same 12E8 layout), 12E8 {off}, 1 byte, type N, unit HEX, unsigned, scale 1, region 447: '{desc}'"),
        evidence=ev,
        width_evidence=(f"move.b ${a:x},d0 @ {mv}; cmp.b (a1),d0 with a1 = #0x80d9dc; cmpi.b #255,${a:x} @ {cmpi}. "
                        "Byte accesses with equality compares only (the decompiler's '== -1' is the 0xFF compare). e2m length 1, unsigned."),
    ))

